begin; create extension if not exists pgtap with schema extensions; select no_plan();
select has_table('public','workout_sessions','sessions table'); select has_table('public','workout_exercises','exercises table'); select has_table('public','workout_sets','sets table');
select has_column('public','workout_sets','planned_metric','planned metric'); select has_column('public','workout_sets','actual_value','actual value'); select has_column('public','workout_sets','actual_load_kg','actual load'); select has_column('public','workout_sets','actual_rir','actual RIR');
select ok(exists(select 1 from pg_indexes where indexname='workout_sessions_one_in_progress_per_athlete'),'one active workout index');
select is((select count(*) from pg_class where relnamespace='public'::regnamespace and relname in ('workout_sessions','workout_exercises','workout_sets') and relrowsecurity),3::bigint,'RLS enabled');
select ok(not has_table_privilege('anon','public.workout_sessions','select'),'anon denied'); select ok(has_table_privilege('authenticated','public.workout_sessions','select'),'athlete can select'); select ok(not has_table_privilege('authenticated','public.workout_sessions','delete'),'client cannot delete');
insert into auth.users(id,email) values('61111111-1111-4111-8111-111111111111','runner-a@example.invalid'),('62222222-2222-4222-8222-222222222222','runner-b@example.invalid');
insert into public.athletes(id,user_id) values('6aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','61111111-1111-4111-8111-111111111111'),('6bbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','62222222-2222-4222-8222-222222222222');
set local request.jwt.claim.sub='61111111-1111-4111-8111-111111111111';set local role authenticated;
insert into public.training_programs(id,athlete_id,name) values('62000000-0000-4000-8000-000000000001',public.current_athlete_id(),'Programa Runner');
select lives_ok($$select public.replace_training_program_structure('62000000-0000-4000-8000-000000000001','{"blocks":[{"sequence":1,"name":"Base","weeks":[{"sequence":1,"days":[{"sequence":1,"name":"Treino A","prescriptions":[{"sequence":1,"exerciseId":"50000000-0000-4000-8000-000000000001","sets":[{"sequence":1,"targetMetric":"reps","targetMin":8,"targetMax":10,"rirMin":2,"rirMax":2,"restMinSeconds":120,"restMaxSeconds":120,"tempo":null,"loadKind":"absolute","loadKg":30},{"sequence":2,"targetMetric":"reps","targetMin":8,"targetMax":10,"rirMin":2,"rirMax":2,"restMinSeconds":120,"restMaxSeconds":120,"tempo":null,"loadKind":"absolute","loadKg":30},{"sequence":3,"targetMetric":"reps","targetMin":8,"targetMax":10,"rirMin":2,"rirMax":2,"restMinSeconds":120,"restMaxSeconds":120,"tempo":null,"loadKind":"absolute","loadKg":30}]}]}]}]}]}'::jsonb)$$);
select lives_ok($$select public.activate_training_program('62000000-0000-4000-8000-000000000001')$$); select lives_ok($$select public.start_workout_session((select id from public.training_days limit 1))$$,'active day starts');
select is((select count(*) from public.workout_sessions),1::bigint,'session created');select is((select count(*) from public.workout_exercises),1::bigint,'exercise copied');select is((select count(*) from public.workout_sets),3::bigint,'sets copied');
select is((select program_name_snapshot from public.workout_sessions),'Programa Runner','program snapshot'); select is((select planned_target_min from public.workout_sets order by sequence limit 1),8::numeric,'target snapshot');
select is((select public.start_workout_session((select id from public.training_days limit 1))),(select id from public.workout_sessions),'duplicate start resumes active'); select is((select count(*) from public.workout_sessions),1::bigint,'no duplicate session');
select lives_ok($$select public.record_workout_set((select id from public.workout_sets where sequence=1),7,30,2::smallint)$$,'below target accepted');select lives_ok($$select public.record_workout_set((select id from public.workout_sets where sequence=2),9,30,1::smallint)$$,'inside target accepted');select lives_ok($$select public.record_workout_set((select id from public.workout_sets where sequence=3),12,27.5,0::smallint)$$,'above target accepted');
select throws_ok($$select public.record_workout_set((select id from public.workout_sets where sequence=1),8.5,30,2::smallint)$$,'23514',null,'fractional reps rejected');select throws_ok($$select public.record_workout_set((select id from public.workout_sets where sequence=1),8,-1,2::smallint)$$,'23514',null,'negative load rejected');select throws_ok($$select public.record_workout_set((select id from public.workout_sets where sequence=1),8,30,11::smallint)$$,'23514',null,'RIR rejected');
select lives_ok($$select public.record_workout_set((select id from public.workout_sets where sequence=1),10,30,2::smallint)$$,'completed set correction allowed');
select lives_ok($$select public.skip_workout_set((select id from public.workout_sets where sequence=3))$$,'skip needs no fake performance');select is((select actual_value from public.workout_sets where sequence=3),null::numeric,'skip clears actual');
select lives_ok($$select public.complete_workout_session((select id from public.workout_sessions))$$,'resolved workout completes');select ok((select completed_at is not null and abandoned_at is null from public.workout_sessions),'completion timestamps');
select throws_ok($$select public.record_workout_set((select id from public.workout_sets limit 1),8,30,2::smallint)$$,'P0002',null,'completed immutable');select throws_ok($$delete from public.workout_sessions$$,'42501',null,'client delete lacks grant');
reset role;set local request.jwt.claim.sub='62222222-2222-4222-8222-222222222222';set local role authenticated;select is((select count(*) from public.workout_sessions),0::bigint,'other athlete cannot read');select throws_ok($$select public.complete_workout_session((select id from public.workout_sessions))$$,'P0002',null,'other athlete cannot mutate');
reset role; select * from finish(); rollback;
